const by=id=>document.getElementById(id),api=()=>globalThis.coexLayerLayout,endpoint='http://127.0.0.1:8191';
const panel=document.createElement('details');panel.id='backgroundRepairPanel';panel.innerHTML=`<summary>가려진 배경 채우기 · OpenAI API</summary><p class="layer-help">남은 배경을 선택해 상품 뒤의 투명 구멍을 채웁니다. 결과는 추정 생성이며 실제 가려진 배경 복원이 아닙니다. 기존 접지 그림자도 정리하려면 아래에서 해당 영역만 칠하세요. 상품 자체의 명암은 수정하지 않습니다. 선택한 배경 사진과 표시한 마스크가 OpenAI에 전송되며 유료 API 비용이 발생합니다. 생성 버튼을 누를 때만 전송합니다. 원래 반투명한 배경은 보존하며 보완 영역에서 제외합니다.</p><button type="button" id="bgRepairPrepare" class="doc-btn">배경 보완 영역 확인</button><label><input type="checkbox" id="bgRepairBrush">남아 있는 그림자 영역도 직접 칠하기</label><label>브러시 크기 <input id="bgRepairSize" type="range" min="10" max="120" value="48"></label><button type="button" id="bgRepairReset" class="doc-btn">추가한 영역 초기화</button><canvas id="bgRepairMask" hidden style="max-width:100%;max-height:500px;touch-action:none;background:repeating-conic-gradient(#ddd 0 25%,#fff 0 50%) 0/16px 16px"></canvas><label>배경 설명 <input id="bgRepairHint" maxlength="300" value="continue the surrounding background texture, surface, perspective and lighting, empty scene without objects"></label><p id="bgRepairStatus" class="layer-help" role="status" aria-live="polite"></p><label><input type="checkbox" id="bgRepairConsent">이번 배경 사진·마스크의 OpenAI 전송과 유료 생성에 동의합니다.</label><button type="button" id="bgRepairRun" class="doc-btn" hidden>표시한 배경 영역 생성</button><button type="button" id="bgRepairCancel" class="doc-btn" hidden>생성 중지</button><img id="bgRepairResult" alt="생성 배경 후보" hidden style="max-width:100%;max-height:400px;object-fit:contain"><button type="button" id="bgRepairApply" class="doc-btn" hidden>배경 후보 적용</button><button type="button" id="bgRepairRestore" class="doc-btn">생성 전 배경으로 복원</button>`;
by('occlusionRepairPanel').after(panel);
const say=t=>by('bgRepairStatus').textContent=t;let prepared=null,candidate=null,busy=false,serial=0,jobId=null,maskCanvas=null,maskStart=null,drag=false,brushLast=null,brushPointer=null;
const selected=()=>api()?.read()?.objects.find(o=>o.canvas)?.canvas?.getActiveObject();
const valid=p=>{const s=api()?.read();return s&&s.epoch===p.state.epoch&&s.revision===p.state.revision&&s.objects.includes(p.object)&&selected()?.photoInstanceGroup===p.object.photoInstanceGroup;};
async function decode(src){const im=new Image();im.src=src;await im.decode();return im;}
function raster(im,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);return c;}
function draw(){if(!prepared||!maskCanvas)return;const c=by('bgRepairMask'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(prepared.image,0,0);const m=maskCanvas.getContext('2d').getImageData(0,0,c.width,c.height),a=m.data;for(let j=0;j<a.length;j+=4){const alpha=prepared.backgroundPixels[j+3],on=a[j]>128&&prepared.originalAlpha[j+3]>0&&(alpha===0||alpha===255);a[j]=a[j+1]=a[j+2]=on?255:0;a[j+3]=255;}maskCanvas.getContext('2d').putImageData(m,0,0);for(let j=0;j<a.length;j+=4){const on=a[j]>128;a[j]=255;a[j+1]=40;a[j+2]=60;a[j+3]=on?160:0;}const overlay=document.createElement('canvas');overlay.width=c.width;overlay.height=c.height;overlay.getContext('2d').putImageData(m,0,0);ctx.drawImage(overlay,0,0);overlay.width=overlay.height=0;}
by('bgRepairPrepare').onclick=async()=>{
 if(busy)return;clearBrush();const state=api()?.read(),active=selected(),o=active?.photoInstanceKind==='background'?active:state?.objects.find(x=>x.photoInstanceGroup===active?.photoInstanceGroup&&x.photoInstanceKind==='background');
 if(!state||!o||o.layerLocked||o.visible===false){say('분리된 배경 또는 같은 그룹의 상품을 선택하고 배경의 잠금을 해제하세요.');return;}
 if(!/^data:image\/png;base64,/i.test(o.getSrc()||'')){say('원래 투명도를 보호하려면 PNG로 저장된 분리 배경을 선택하세요.');return;}
 const source=state.objects.find(x=>x.photoInstanceGroup===o.photoInstanceGroup&&x.photoInstanceKind==='source');if(!source?.originalPhotoSource){say('보관된 원본 사진이 필요합니다.');return;}
 const token=++serial;candidate=null;by('bgRepairApply').hidden=true;by('bgRepairResult').hidden=true;
 try{const image=await decode(o.getSrc()),original=await decode(source.originalPhotoSource);if(token!==serial)return;if(image.naturalWidth!==original.naturalWidth||image.naturalHeight!==original.naturalHeight)throw Error('배경과 원본 규격이 다릅니다.');const w=image.naturalWidth,h=image.naturalHeight;if(w*h>4000000)throw Error('배경이 너무 큽니다.');
  const c=raster(image,w,h),a=c.getContext('2d').getImageData(0,0,w,h),oc=raster(original,w,h),rgb=oc.getContext('2d').getImageData(0,0,w,h).data;c.width=c.height=oc.width=oc.height=0;maskCanvas=document.createElement('canvas');maskCanvas.width=w;maskCanvas.height=h;const m=maskCanvas.getContext('2d').createImageData(w,h);let count=0;for(let i=0;i<w*h;i++){const j=i*4,on=a.data[j+3]===0&&rgb[j+3]>0;m.data[j]=m.data[j+1]=m.data[j+2]=on?255:0;m.data[j+3]=255;if(on)count++;}maskCanvas.getContext('2d').putImageData(m,0,0);maskStart=new Uint8ClampedArray(m.data);prepared={state,object:o,image,originalAlpha:rgb,backgroundPixels:a.data,source:o.getSrc(),count};if(!valid(prepared)){prepared=null;return;}
  by('bgRepairMask').width=w;by('bgRepairMask').height=h;by('bgRepairMask').hidden=false;by('bgRepairRun').hidden=false;draw();say(count.toLocaleString()+'픽셀의 구멍을 확인했습니다. 원래 반투명 영역은 보존해 빨간 범위에서 제외합니다. 남은 그림자를 추가로 칠하고 생성 전 범위를 확인하세요.');
 }catch(e){say(e.message);}
};
by('bgRepairReset').onclick=()=>{if(!busy&&prepared&&maskStart){clearBrush();maskCanvas.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(maskStart),maskCanvas.width,maskCanvas.height),0,0);candidate=null;by('bgRepairApply').hidden=true;draw();}};
function clearBrush(){drag=false;brushLast=null;brushPointer=null;}
function stopBrush(e){if(brushPointer!==null&&e.pointerId!==brushPointer)return;clearBrush();}
function brush(e){if(!drag||e.pointerId!==brushPointer)return;if(busy||!prepared||!by('bgRepairBrush').checked){brushLast=null;return;}const c=by('bgRepairMask'),b=c.getBoundingClientRect();if(!(b.width>0&&b.height>0)){brushLast=null;return;}const x=(e.clientX-b.left)*c.width/b.width,y=(e.clientY-b.top)*c.height/b.height,ctx=maskCanvas.getContext('2d'),size=Number(by('bgRepairSize').value),sameFrame=brushLast&&['left','top','width','height'].every(k=>Math.abs(brushLast.frame[k]-b[k])<.5);ctx.fillStyle=ctx.strokeStyle='#fff';ctx.lineWidth=size;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();if(sameFrame){ctx.moveTo(brushLast.x,brushLast.y);ctx.lineTo(x,y);ctx.stroke();}else{ctx.arc(x,y,size/2,0,Math.PI*2);ctx.fill();}brushLast={x,y,frame:{left:b.left,top:b.top,width:b.width,height:b.height}};candidate=null;by('bgRepairApply').hidden=true;draw();}
by('bgRepairMask').onpointerdown=e=>{if(drag)return;drag=true;brushLast=null;brushPointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);brush(e);};by('bgRepairMask').onpointermove=brush;by('bgRepairMask').onpointerup=stopBrush;by('bgRepairMask').onpointercancel=stopBrush;by('bgRepairMask').onlostpointercapture=stopBrush;
async function cancel(){serial++;busy=false;const key=jobId;jobId=null;by('bgRepairRun').disabled=false;by('bgRepairCancel').hidden=true;if(key)try{await fetch(endpoint+'/jobs/'+key+'/cancel',{method:'POST'});}catch{}}
by('bgRepairCancel').onclick=()=>{cancel();say('배경 생성을 중지했습니다. 현재 배경은 유지합니다.');};
async function dataUrl(id,file){const r=await fetch(endpoint+'/jobs/'+id+'/'+file);if(!r.ok)throw Error('후보 이미지 연결 실패');const blob=await r.blob();return new Promise(resolve=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.readAsDataURL(blob);});}
by('bgRepairRun').onclick=async()=>{
 const p=prepared;if(!by('bgRepairConsent').checked){say('이번 배경 사진·마스크의 전송과 유료 생성에 동의해 주세요.');return;}if(busy||!p||!valid(p)){say('배경 영역을 다시 확인하세요.');return;}
 const token=++serial;clearBrush();busy=true;by('bgRepairRun').disabled=true;by('bgRepairCancel').hidden=false;by('bgRepairApply').hidden=true;say('선택한 배경과 마스크를 OpenAI로 전송해 후보를 만듭니다.');
 try{const h=await fetch(endpoint+'/health').then(r=>r.json());if(!h.openaiReady)throw Error('프로젝트 폴더의 빵보완_API설정.cmd에서 API 키를 설정하세요.');if(h.busy)throw Error('다른 분석 또는 생성 작업이 끝난 뒤 다시 실행하세요.');const m=maskCanvas.getContext('2d').getImageData(0,0,maskCanvas.width,maskCanvas.height);let count=0;for(let i=0;i<maskCanvas.width*maskCanvas.height;i++){const j=i*4,alpha=p.backgroundPixels[j+3],on=m.data[j]>128&&p.originalAlpha[j+3]>0&&(alpha===0||alpha===255);m.data[j]=m.data[j+1]=m.data[j+2]=on?255:0;m.data[j+3]=255;if(on)count++;}if(!count||count>maskCanvas.width*maskCanvas.height*.8)throw Error('보완 영역이 없거나 너무 넓습니다. 영역을 줄이세요.');const source=p.source;maskCanvas.getContext('2d').putImageData(m,0,0);const mask=maskCanvas.toDataURL();
  by('bgRepairConsent').checked=false;const response=await fetch(endpoint+'/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:'openai',task:'background',externalConsent:true,sourceUnmodifiedVersion:'background-source-unmodified-v1',source,mask,hint:by('bgRepairHint').value,matte:'#5f4b3d',fresh:true})});const job=await response.json();if(!response.ok)throw Error(job.error);if(token!==serial){await fetch(endpoint+'/jobs/'+job.id+'/cancel',{method:'POST'});return;}jobId=job.id;
  while(token===serial){await new Promise(r=>setTimeout(r,1200));if(!valid(p)){await cancel();say('편집 상태가 바뀌어 배경 생성을 취소했습니다.');return;}const j=await fetch(endpoint+'/jobs/'+job.id).then(r=>r.json());say((j.phase||'배경 생성 중')+(j.progress!==undefined?' · '+j.progress+'%':''));if(j.status==='failed')throw Error(j.error);if(j.status==='cancelled')return;if(j.status!=='completed')continue;if(j.result.protectedRgbChanged!==0||j.result.method!=='openai-background-inpainting')throw Error('배경 전용 결과 검증 실패');const src=await dataUrl(job.id,j.result.image),actualMask=await dataUrl(job.id,j.result.mask);if(token!==serial||!valid(p))return;candidate={...p,src,mask:actualMask};by('bgRepairResult').src=src;by('bgRepairResult').hidden=false;by('bgRepairApply').hidden=false;say('배경 후보입니다. 접지 그림자·무늬·연결 경계를 확인한 뒤 적용하세요. 지정한 범위 밖의 배경은 보존합니다.');break;}
 }catch(e){say('배경 생성 확인 필요: '+e.message+' 현재 배경은 유지합니다.');}finally{if(token===serial){busy=false;jobId=null;by('bgRepairRun').disabled=false;by('bgRepairCancel').hidden=true;}}
};
by('bgRepairApply').onclick=async()=>{const p=candidate;if(!p||!valid(p))return;const image=await decode(p.src);if(!valid(p))return;p.object.generatedPhotoSource=p.object.generatedPhotoSource||p.source;p.object.generatedRegionMask=p.mask;p.object.generatedMethod='openai-background-inpainting';p.object.setElement(image);api().commit(p.state.width,p.state.height,{epoch:p.state.epoch,revision:p.state.revision,apply:true});candidate=prepared=null;by('bgRepairApply').hidden=true;say('배경 레이어에만 적용했습니다. 상품과 문구는 독립 요소로 유지합니다.');};
by('bgRepairRestore').onclick=async()=>{const s=api()?.read(),o=selected();if(o?.photoInstanceKind!=='background'||!o.generatedPhotoSource){say('보완된 배경 레이어를 선택하세요.');return;}const image=await decode(o.generatedPhotoSource);if(api()?.read()?.epoch!==s.epoch||api()?.read()?.revision!==s.revision)return;o.setElement(image);delete o.generatedPhotoSource;delete o.generatedRegionMask;delete o.generatedMethod;api().commit(s.width,s.height,{epoch:s.epoch,revision:s.revision,apply:true});say('생성 전 배경으로 복원했습니다.');};
